// femacs: port of src/alloc.c @ fd7afced403.
//
// One-to-one port (PORTING.md): same statements in the same order, same names (function,
// struct, struct field, macro, file-scope object, local), same control flow, same error
// model.  The twenty-two `DEFUN`s use `DEFUN!` (PORTING.md 5.1); C's non-`static` definitions
// carry `#[unsafe(no_mangle)]` (PORTING.md 0.2) and the C `static` helpers stay plain
// `unsafe fn`.
//
// **Carried arms.**  `src/alloc.c` is *not* in `docs/baseline/config/cond-eval-verified.txt`
// (`python3 tools/check-cond-eval.py src/alloc.c` reports `138 conditions, 0 unknown,
// 4 disagreements [NOT VERIFIED]`: the frozen macro table has no `USE_LSB_TAG`, which
// `lisp.h` requires to be 1, so the four `! USE_LSB_TAG` conditions read the other way round
// for the evaluator than for clang; the arms below follow clang, measured on this target —
// every branch of the file's 166 conditional lines was probed with `clang -dM -E` against
// `build/emacs-ref/src/config.h`).  The file is therefore *blind* for
// `tools/extract-abi.py`: it keeps both arms of every `#if` live, so the per-function token
// check demands the text of the arms the frozen build does not compile too (docs/status.md
// 3.49; `term.rs`/`font.rs` are the precedents).  The live arms are ordinary text below; the
// dead ones are carried as `#[cfg (feature = "…")]` text naming the non-frozen side of C's
// condition, and none of those features is ever set (`xtask`'s `dead-arms` can only flip the
// keys `config.rs` carries, and these are this file's platform/preprocessor predicates —
// docs/status.md 3.9).  Dead on this target: `HAVE_MALLOC_H`, `HAVE_WINDOW_SYSTEM`,
// `HAVE_ANDROID`, `HAVE_TREE_SITTER`, `HAVE_LINUX_SYSINFO`, `MSDOS`, `WINDOWSNT`, `USE_GTK`,
// `HAVE_PGTK`, `HAVE_HAIKU`, `HAVE_X_WINDOWS`, `HAVE_NS`, `HAVE_TEXT_CONVERSION`,
// `ENABLE_CHECKING`, `USE_VALGRIND`, `ADDRESS_SANITIZER`, `DOUG_LEA_MALLOC`,
// `HAVE_POSIX_MEMALIGN`, `GC_MALLOC_CHECK`, `GC_CHECK_STRING_BYTES`, `GC_CHECK_STRING_OVERRUN`,
// `GC_CHECK_STRING_FREE_LIST`, `GC_ASAN_POISON_OBJECTS`, `GC_MARK_SECONDARY_STACK`,
// `GC_CDR_COUNT`, `HAVE_MODULES`, `HAVE_NATIVE_COMP`, `HAVE_MALLOC_TRIM`, `USE_LSB_TAG`,
// `SIGDANGER`, `__i386` and `REL_ALLOC`; live are `HAVE_PTHREAD`, `HAVE_PDUMPER`,
// `MAX_SAVE_STACK > 0`, `HAVE___BUILTIN_UNWIND_INIT`, `GC_REMEMBER_LAST_MARKED`,
// `GC_STRING_EXTRA` and C 7620's `__GNUC__`.  `#if 0` regions (C 176-186 in
// `union emacs_align_type`, C 1409-1410) are dead in every configuration and are recorded in
// `docs/ports/alloc.md`, not transcribed (docs/status.md 3.55's rule).
//
// **Use-site declarations (mirror gaps).**  `emacs/src/alloc.h` exists but has no mirror, and
// several headers this file includes have none either; the names the mirror chain below does
// not carry are declared at their use site with C's own prototype in a `/// C:` line
// (PORTING.md 0.1-2/P-72 rule ③).  The mirror gaps this unit reports and does not touch are
// listed in `docs/ports/alloc.md`.
//
// **`struct emacs_globals globals`.**  C 278 defines the single `globals` object whose fields
// the `DEFVAR_*` macros name; `globals.h` (generated by `make-docfile`) has no mirror, so the
// port declares the record at its use site and defines the object as an opaque cell — nothing
// reads it, and each `V*` this unit owns is the separate object of docs/status.md 3.29's shape
// ①, the deviation the whole tree carries until `globals.h` is mirrored (3.29 ④).

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code,
         unused_imports, unused_macros, unused_variables, unused_mut, unused_assignments,
         unused_unsafe, static_mut_refs, unsafe_op_in_unsafe_fn, unused_parens,
         clashing_extern_declarations, unused_comparisons, overflowing_literals,
         unreachable_code, unused_labels, while_true, unused_must_use)]

